{
  "name": "Infection Control Training Manager",
  "description": "A comprehensive dashboard for managing hospital infection control training, including scheduling, logging, and reporting."
}

/**
 * Server-side logic for Infection Training Web App
 */

// Global Constants
const SPREADSHEET_NAME = "Infection Training";
const SHEET_EMPLOYEES = "Employees";
const SHEET_LOGS = "TrainingLogs";
const SHEET_SETTINGS = "Settings";
const SHEET_PLAN = "TrainingPlan";

// Categories fixed as per requirement
const CATEGORIES = ["أطباء", "تمريض", "عمال", "فئات أخرى"];

/**
 * Serves the React Web App
 */
function doGet() {
  return HtmlService.createTemplateFromFile('index')
    .evaluate()
    .setTitle('برنامج التدريب - مكافحة العدوى')
    .addMetaTag('viewport', 'width=device-width, initial-scale=1')
    .setXFrameOptionsMode(HtmlService.XFrameOptionsMode.ALLOWALL);
}

/**
 * Initial setup to ensure Spreadsheet exists
 */
function getOrCreateSpreadsheet() {
  const files = DriveApp.getFilesByName(SPREADSHEET_NAME);
  if (files.hasNext()) {
    return SpreadsheetApp.open(files.next());
  }
  const ss = SpreadsheetApp.create(SPREADSHEET_NAME);
  return ss;
}

/**
 * Helper to get data from a sheet
 */
function getSheetData(sheetName) {
  const ss = getOrCreateSpreadsheet();
  let sheet = ss.getSheetByName(sheetName);

  if (!sheet) {
    sheet = ss.insertSheet(sheetName);
    // Initialize headers if new
    if (sheetName === SHEET_EMPLOYEES) sheet.appendRow(["ID", "Name", "Job", "Category"]);
    if (sheetName === SHEET_LOGS) sheet.appendRow(["ID", "Date", "Month", "Year", "Category", "Policies", "TraineeName", "Trainer", "Timestamp"]);
    if (sheetName === SHEET_SETTINGS) {
       sheet.appendRow(["Type", "Value"]); // Type: Policy, Trainer
       // Add default policies/trainers for demo
       sheet.appendRow(["Policy", "غسل الأيدي"]);
       sheet.appendRow(["Policy", "التعامل مع الانسكابات"]);
       sheet.appendRow(["Trainer", "د. محمد أحمد"]);
    }
    if (sheetName === SHEET_PLAN) sheet.appendRow(["Month", "Category", "Policies"]);
  }

  const data = sheet.getDataRange().getValues();
  const headers = data.shift();
  return data.map(row => {
    let obj = {};
    headers.forEach((h, i) => obj[h] = row[i]);
    return obj;
  });
}

/**
 * API: Get all initial data
 */
function getAllData() {
  return {
    employees: getSheetData(SHEET_EMPLOYEES),
    logs: getSheetData(SHEET_LOGS),
    settings: getSheetData(SHEET_SETTINGS),
    plan: getSheetData(SHEET_PLAN),
    categories: CATEGORIES
  };
}

/**
 * API: Save a new Training Session
 */
function saveTrainingSession(data) {
  const ss = getOrCreateSpreadsheet();
  const sheet = ss.getSheetByName(SHEET_LOGS);

  const timestamp = new Date();
  const month = new Date(data.date).getMonth() + 1; // 1-12
  const year = new Date(data.date).getFullYear();

  // Save each trainee as a separate row for easier filtering later, 
  // or logic can group them. Based on requirements, we need to track individuals.
  // Data.trainees is an array of names. Data.policies is array of strings.

  const newRows = [];

  data.trainees.forEach(trainee => {
    const id = Utilities.getUuid();
    // Flatten policies to string for display, but analysis might split them. 
    // Requirement says "person trained on policy twice". 
    // We will save one row per policy per person to make math easier? 
    // Or one row per session containing multiple policies.
    // Let's do one row per session, comma separated policies.

    newRows.push([
      id,
      data.date,
      month,
      year,
      data.category,
      data.policies.join(","),
      trainee,
      data.trainer,
      timestamp
    ]);
  });

  if (newRows.length > 0) {
    sheet.getRange(sheet.getLastRow() + 1, 1, newRows.length, newRows[0].length).setValues(newRows);
  }

  return getAllData(); // Return fresh data
}

/**
 * API: Manage Employees (Add/Edit/Delete not fully impl in this snippet, just Add)
 */
function addEmployee(employee) {
  const ss = getOrCreateSpreadsheet();
  const sheet = ss.getSheetByName(SHEET_EMPLOYEES);
  const id = Utilities.getUuid();
  sheet.appendRow([id, employee.name, employee.job, employee.category]);
  return getAllData();
}

/**
 * API: Update Settings (Policies, Trainers, Plan)
 * This is a simplified "replace all" or "append" strategy.
 */
function saveSettingsItem(type, value) {
   const ss = getOrCreateSpreadsheet();
   const sheet = ss.getSheetByName(SHEET_SETTINGS);
   sheet.appendRow([type, value]);
   return getAllData();
}

function deleteSettingsItem(type, value) {
  const ss = getOrCreateSpreadsheet();
  const sheet = ss.getSheetByName(SHEET_SETTINGS);
  const data = sheet.getDataRange().getValues();

  for (let i = data.length - 1; i >= 0; i--) {
    if (data[i][0] == type && data[i][1] == value) {
      sheet.deleteRow(i + 1);
    }
  }
  return getAllData();
}

function savePlan(planData) {
   // planData: { month, category, policies: [] }
   const ss = getOrCreateSpreadsheet();
   const sheet = ss.getSheetByName(SHEET_PLAN);

   // Check if exists and update, or append
   const data = sheet.getDataRange().getValues();
   let found = false;

   for(let i=1; i<data.length; i++) {
     if(data[i][0] == planData.month && data[i][1] == planData.category) {
       sheet.getRange(i+1, 3).setValue(planData.policies.join(","));
       found = true;
       break;
     }
   }

   if(!found) {
     sheet.appendRow([planData.month, planData.category, planData.policies.join(",")]);
   }
   return getAllData();
}

function importEmployees(dataArray) {
   // dataArray = [[name, job, category], ...]
   const ss = getOrCreateSpreadsheet();
   const sheet = ss.getSheetByName(SHEET_EMPLOYEES);
   const rows = dataArray.map(r => [Utilities.getUuid(), r[0], r[1], r[2]]);
   if(rows.length > 0) {
     sheet.getRange(sheet.getLastRow() + 1, 1, rows.length, rows[0].length).setValues(rows);
   }
   return getAllData();
}

