    if (!url) throw new Error("الرابط غير موجود");

    const ss = SpreadsheetApp.openByUrl(url);
    const sheet = ss.getSheets()[0]; // Read first sheet
    const rawData = sheet.getDataRange().getValues();

    // Check for header row to skip (simple heuristic: checks for 'Name' or 'الاسم')
    if (rawData.length > 0) {
      const header = rawData[0][0].toString().toLowerCase();
      if (header.includes("name") || header.includes("اسم")) {
        rawData.shift();
      }
    }

    const targetSS = getOrCreateSpreadsheet();
    const targetSheet = targetSS.getSheetByName(SHEET_EMPLOYEES);

    const rowsToAdd = [];

    rawData.forEach(row => {
      // Assumes: Col 1 = Name, Col 2 = Job, Col 3 = Category
      const name = row[0];
      const job = row[1] || "";
      const category = row[2] || "فئات أخرى";

      if (name && name.toString().trim() !== "") {
        rowsToAdd.push([
          Utilities.getUuid(),
          name,
          job,
          category
        ]);
      }
    });

    if (rowsToAdd.length > 0) {
      targetSheet.getRange(targetSheet.getLastRow() + 1, 1, rowsToAdd.length, rowsToAdd[0].length).setValues(rowsToAdd);
    }

    return getAllData();
  } catch (e) {
    throw new Error("فشل الاستيراد: " + e.message);
  }
}

