/**
 * Helper to get data from a sheet with safe date serialization and trimming
 */
function getSheetData(sheetName) {
  const ss = getOrCreateSpreadsheet();
  let sheet = ss.getSheetByName(sheetName);

  if (!sheet) {
    sheet = ss.insertSheet(sheetName);
    if (sheetName === SHEET_EMPLOY_EMPLOYEES) sheet.appendRow(["ID", "Name", "Job", "Category"]);
    if (sheetName === SHEET_LOGS) sheet.appendRow(["ID", "Date", "Month", "Year", "Category", "Policies", "TraineeName", "Trainer", "Timestamp"]);
    if (sheetName === SHEET_SETTINGS) {
       sheet.appendRow(["Type", "Value"]);
       sheet.appendRow(["Policy", "غسل الأيدي"]);
       sheet.appendRow(["Policy", "التعامل مع الانسكابات"]);
       sheet.appendRow(["Trainer", "د. محمد أحمد"]);
    }
    if (sheetName === SHEET_PLAN) sheet.appendRow(["Month", "Category", "Policies"]);
  }

  const range = sheet.getDataRange();
  const values = range.getValues();

  if (values.length < 1) return [];

  const headers = values.shift(); 

  return values.map(row => {
    let obj = {};
    headers.forEach((h, i) => {
      const val = row[i];
      if (val instanceof Date) {
        obj[h] = val.toISOString();
      } else {
        // Trim strings to prevent matching issues with categories
        obj[h] = (typeof val === 'string') ? val.trim() : val;
      }
    });
    return obj;
  });
}

