/**
 * API: Save Training Plan
 */
function savePlan(planData) {
   const ss = getOrCreateSpreadsheet();
   const sheet = ss.getSheetByName(SHEET_PLAN);
   const data = sheet.getDataRange().getValues();
   let found = false;

   for(let i=1; i<data.length; i++) {
     if(data[i][0] == planData.month && data[i][1] == planData.category) {
       sheet.getRange(i+1, 3).setValue(planData.policies.join(","));
       found = true;
       break;
     }
   }

   if(!found) {
     sheet.appendRow([planData.month, planData.category, planData.policies.join(",")]);
   }
   return getAllData();
}

/**
 * API: Import Employees from External Sheet URL
 */
function importFromExternalSheet(url) {
  try {
    if (!url) throw new Error("الرابط غير موجود");
    const ss = SpreadsheetApp.openByUrl(url);
    const sheet = ss.getSheets()[0];
    const rawData = sheet.getDataRange().getValues();

    if (rawData.length > 0) {
      const header = rawData[0][0].toString().toLowerCase();
      if (header.includes("name") || header.includes("اسم")) rawData.shift();
    }

    const targetSS = getOrCreateSpreadsheet();
    const targetSheet = targetSS.getSheetByName(SHEET_EMPLOYEES);

    const rowsToAdd = rawData.filter(row => row[0]).map(row => [
      Utilities.getUuid(),
      row[0].toString().trim(),
      (row[1] || "").toString().trim(),
      (row[2] || "فئات أخرى").toString().trim()
    ]);

    if (rowsToAdd.length > 0) {
      targetSheet.getRange(targetSheet.getLastRow() + 1, 1, rowsToAdd.length, rowsToAdd[0].length).setValues(rowsToAdd);
    }

    return getAllData();
  } catch (e) {
    throw new Error("فشل الاستيراد: " + e.message);
  }
}

