      const firstCell = String(rawData[0][0] || "").toLowerCase();
      if (firstCell.includes("اسم") || firstCell.includes("name")) rawData.shift();
    }
    const targetSheet = getOrCreateSpreadsheet().getSheetByName(SHEET_EMPLOYEES);
    const rows = rawData.filter(r => r[0]).map(r => [
      Utilities.getUuid(), 
      String(r[0]).trim(), 
      String(r[1] || "").trim(), 
      String(r[2] || "فئات أخرى").trim()
    ]);
    if (rows.length > 0) targetSheet.getRange(targetSheet.getLastRow() + 1, 1, rows.length, rows[0].length).setValues(rows);
    return getAllData();
  } catch (e) { 
    throw new Error("خطأ في الاستيراد: " + e.message); 
  }
}

/**
 * Server-side logic for Infection Training Web App
 */

const SPREADSHEET_NAME = "Infection Training";
const SHEET_EMPLOYEES = "Employees";
const SHEET_LOGS = "TrainingLogs";
const SHEET_SETTINGS = "Settings";
const SHEET_PLAN = "TrainingPlan";
const CATEGORIES = ["أطباء", "تمريض", "عمال", "فئات أخرى"];

function doGet() {
  return HtmlService.createTemplateFromFile('index')
    .evaluate()
    .setTitle('نظام تدريب مكافحة العدوى المطور')
    .addMetaTag('viewport', 'width=device-width, initial-scale=1')
    .setXFrameOptionsMode(HtmlService.XFrameOptionsMode.ALLOWALL);
}

function getOrCreateSpreadsheet() {
  const files = DriveApp.getFilesByName(SPREADSHEET_NAME);
  while (files.hasNext()) {
    const file = files.next();
    if (file.getMimeType() === MimeType.GOOGLE_SHEETS) return SpreadsheetApp.openById(file.getId());
  }
  return SpreadsheetApp.create(SPREADSHEET_NAME);
}

function getSheetData(sheetName) {
  const ss = getOrCreateSpreadsheet();
  let sheet = ss.getSheetByName(sheetName);
  if (!sheet) {
    sheet = ss.insertSheet(sheetName);
    if (sheetName === SHEET_EMPLOYEES) sheet.appendRow(["ID", "Name", "Job", "Category"]);
    if (sheetName === SHEET_LOGS) sheet.appendRow(["ID", "Date", "Month", "Year", "Category", "Policies", "TraineeName", "Trainer", "Timestamp"]);
    if (sheetName === SHEET_SETTINGS) {
       sheet.appendRow(["Type", "Value"]);
       sheet.appendRow(["Policy", "غسل الأيدي"]);
       sheet.appendRow(["Trainer", "مدرب مكافحة العدوى"]);
    }
    if (sheetName === SHEET_PLAN) sheet.appendRow(["Month", "Category", "Policies"]);
  }
  const values = sheet.getDataRange().getValues();
  if (values.length <= 1) return [];
  const headers = values.shift();
  return values.map(row => {
    let obj = {};
    headers.forEach((h, i) => {
      let val = row[i];
      if (val instanceof Date) obj[h] = val.toISOString();
      else obj[h] = (typeof val === 'string') ? val.trim() : (val === undefined || val === null ? "" : val);
    });
    return obj;
  });
}

function getAllData() {
  try {
    return {
      employees: getSheetData(SHEET_EMPLOYEES),
      logs: getSheetData(SHEET_LOGS),
      settings: getSheetData(SHEET_SETTINGS),
      plan: getSheetData(SHEET_PLAN),
      categories: CATEGORIES
    };
  } catch (e) { 
    Logger.log(e.message);
    throw new Error("فشل جلب البيانات: " + e.message); 
  }
}

function saveTrainingSession(data) {
  const ss = getOrCreateSpreadsheet();
  const sheet = ss.getSheetByName(SHEET_LOGS);
  const timestamp = Utilities.formatDate(new Date(), Session.getScriptTimeZone(), "yyyy-MM-dd HH:mm:ss");
  const dateObj = new Date(data.date);
  const rows = data.trainees.map(t => [
    Utilities.getUuid(), 
    data.date, 
    dateObj.getMonth() + 1, 
    dateObj.getFullYear(), 
    data.category.trim(), 
    data.policies.join(", "), 
    t.trim(), 
    data.trainer.trim(), 
    timestamp
  ]);
  if (rows.length > 0) sheet.getRange(sheet.getLastRow() + 1, 1, rows.length, rows[0].length).setValues(rows);
  return getAllData();
}

function savePlan(planData) {
  const ss = getOrCreateSpreadsheet();
  let sheet = ss.getSheetByName(SHEET_PLAN);
  if (!sheet) sheet = ss.insertSheet(SHEET_PLAN);

  const values = sheet.getDataRange().getValues();
  let foundRow = -1;
  for (let i = 1; i < values.length; i++) {
    if (values[i][0] == planData.month && values[i][1] == planData.category) {
      foundRow = i + 1;
      break;
    }
  }

  const policiesStr = planData.policies.join(", ");
  if (foundRow > 0) {
    sheet.getRange(foundRow, 3).setValue(policiesStr);
  } else {
    sheet.appendRow([planData.month, planData.category, policiesStr]);
  }
  return getAllData();
}

function updateEmployeesBulk(updatedEmployees) {
  const ss = getOrCreateSpreadsheet();
  const sheet = ss.getSheetByName(SHEET_EMPLOYEES);
  const headers = ["ID", "Name", "Job", "Category"];
  const newData = [headers];
  updatedEmployees.forEach(emp => {
    if (emp.Name) newData.push([emp.ID || Utilities.getUuid(), emp.Name.trim(), (emp.Job || "").trim(), (emp.Category || "فئات أخرى").trim()]);
  });
  sheet.clearContents();
  sheet.getRange(1, 1, newData.length, headers.length).setValues(newData);
  return getAllData();
}

function deleteEmployee(id) {
  const ss = getOrCreateSpreadsheet();
  const sheet = ss.getSheetByName(SHEET_EMPLOYEES);
  const data = sheet.getDataRange().getValues();
  for (let i = 1; i < data.length; i++) {
    if (data[i][0] == id) { sheet.deleteRow(i + 1); break; }
  }
  return getAllData();
}

function saveSettingsItem(type, value) {
  const ss = getOrCreateSpreadsheet();
  const sheet = ss.getSheetByName(SHEET_SETTINGS);
  sheet.appendRow([type, value.trim()]);
  return getAllData();
}

function deleteSettingsItem(type, value) {
  const ss = getOrCreateSpreadsheet();
  const sheet = ss.getSheetByName(SHEET_SETTINGS);
  const data = sheet.getDataRange().getValues();
  for (let i = data.length - 1; i >= 0; i--) {
    if (data[i][0] == type && data[i][1] == value) sheet.deleteRow(i + 1);
  }
  return getAllData();
}

function importFromExternalSheet(url) {
  try {
    const ss = SpreadsheetApp.openByUrl(url);
    const rawData = ss.getSheets()[0].getDataRange().getValues();
    if (rawData.length > 0) {
      const firstCell = String(rawData[0][0] || "").toLowerCase();
      if (firstCell.includes("اسم") || firstCell.includes("name")) rawData.shift();
    }
    const targetSheet = getOrCreateSpreadsheet().getSheetByName(SHEET_EMPLOYEES);
    const rows = rawData.filter(r => r[0]).map(r => [
      Utilities.getUuid(), 
      String(r[0]).trim(), 
      String(r[1] || "").trim(), 
      String(r[2] || "فئات أخرى").trim()
    ]);
    if (rows.length > 0) targetSheet.getRange(targetSheet.getLastRow() + 1, 1, rows.length, rows[0].length).setValues(rows);
    return getAllData();
  } catch (e) { 
    throw new Error("خطأ في الاستيراد: " + e.message); 
  }
}

const TrainingPage = ({ data, refreshData }) => {
    const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
    const [category, setCategory] = useState(data.categories[0]);
    const [selectedPolicies, setSelectedPolicies] = useState([]);
    const [trainer, setTrainer] = useState("");
    const [search, setSearch] = useState("");
    const [selectedTrainees, setSelectedTrainees] = useState([]);
    const [showMobileDetails, setShowMobileDetails] = useState(false);
    const [isSaving, setIsSaving] = useState(false);
    const showToast = useToast();

    const currentMonth = new Date(date).getMonth() + 1;
    const policies = data.settings.filter(s => s.Type === "Policy").map(s => s.Value);
    const trainers = data.settings.filter(s => s.Type === "Trainer").map(s => s.Value);

    const plannedPoliciesForThis = useMemo(() => {
        const planItem = data.plan.find(p => p.Month == currentMonth && p.Category === category);
        return planItem ? planItem.Policies.split(", ").map(p => p.trim()) : [];
    }, [data.plan, category, currentMonth]);

    useEffect(() => { setSelectedPolicies(plannedPoliciesForThis); }, [plannedPoliciesForThis]);

    const filteredEmployees = useMemo(() => {
        return data.employees.filter(emp => (emp.Category || "").trim() === (category || "").trim() && (!search || emp.Name.toLowerCase().includes(search.toLowerCase())));
    }, [data.employees, category, search]);

    const handleSave = async () => {
        if (!selectedPolicies.length || !selectedTrainees.length || !trainer) return showToast("يرجى استكمال البيانات (المتدربين، المواضيع، المدرب)", "error");
        setIsSaving(true);
        try {
            const res = await runServer('saveTrainingSession', { date, category, policies: selectedPolicies, trainees: selectedTrainees, trainer });
            refreshData(res);
            setSelectedTrainees([]);
            showToast("تم حفظ التدريب بنجاح");
        } catch (e) { showToast(e.message, "error"); }
        finally { setIsSaving(false); }
    };

    return (
        <div className="max-w-7xl mx-auto p-4 lg:p-6 space-y-4 lg:space-y-6 fade-in h-full flex flex-col lg:block pb-6 relative">
             <header className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-2 slide-up">
                <div className="flex justify-between items-center w-full md:w-auto">
