                            <div>
                                <label className="block text-xs font-bold text-slate-400 mb-1">القائم بالتدريب</label>
                                <select value={trainer} onChange={e => setTrainer(e.target.value)} className="input-base cursor-pointer text-sm lg:text-base hover:border-indigo-200">
                                    <option value="">اختر المدرب...</option>
